            if c in seen:
                seen[c].append((ridx, pos))
            else:
                seen[c] = [(ridx, pos)]

    missing = []
    for c in customers:
        if c not in seen:
            missing.append(c)

    if missing:
        # Remove duplicates beyond first occurrence and insert missing greedily.
        keep = set()
        for ridx in range(len(routes)):
            newr = []
            for c in routes[ridx]:
                if c not in keep:
                    keep.add(c)
                    newr.append(c)
            routes[ridx] = newr
        # Re-add missing customers.
        for node in missing:
            best_r = None
            best_pos = None
            best_delta = None
            for ridx, r in enumerate(routes):
                if rload(r) + demands[node] > capacity:
                    continue
                for pos in range(len(r) + 1):
                    if len(r) == 0:
                        delta = 0
                    elif pos == 0:
                        delta = dist[depot][node] + dist[node][r[0]] - dist[depot][r[0]]
                    elif pos == len(r):
                        delta = dist[r[-1]][node] + dist[node][depot] - dist[r[-1]][depot]
                    else:
                        a = r[pos - 1]
                        b = r[pos]
                        delta = dist[a][node] + dist[node][b] - dist[a][b]
                    if best_delta is None or delta < best_delta or (delta == best_delta and (ridx, pos) < (best_r, best_pos)):
                        best_delta = delta
                        best_r = ridx
                        best_pos = pos
            if best_r is None:
                routes.append([node])
            else:
                routes[best_r] = routes[best_r][:best_pos] + [node] + routes[best_r][best_pos:]

    # Remove any accidental empty routes.
    routes = [r for r in routes if r]

    return routes
